Field.Calculation:
Let ([
~tsraw = JSONGetElementValid ( PrinterPresence::messageClean ; "date_created" ) ;
~l  = Substitute ( ~tsraw ; [ ":" ; ¶ ] ; [ "-" ; ¶ ] ; [ " " ; ¶ ] ; [ "T" ; ¶ ] ; [ "+" ; ¶ ] ) ;
~y  = GetValue ( ~l ; 1 ) ;
~mo = GetValue ( ~l ; 2 ) ;
~d  = GetValue ( ~l ; 3 ) ;
~h  = GetValue ( ~l ; 4 ) ;
~mi = GetValue ( ~l ; 5 ) ;
~s  = GetValue ( ~l ; 6 )
] ;
If ( IsEmpty ( ~tsraw ) ; "" ;
	Timestamp ( Date ( ~mo ; ~d ; ~y ) ; Time ( ~h ; ~mi ; ~s ) )
)
)

