Field.Calculation:
Let ([
~a = JSONGetElementValid ( PrinterPresence::messageClean ; "payload.message.payment_transactions.data[]amount" )
] ;
If ( IsEmpty ( ~a ) ; "" ;
	If ( PatternCount ( ~a ; "." ) ;
		GetAsNumber ( ~a ) ;
		Round ( GetAsNumber ( ~a ) / 100 ; 2 )
	)
)
)

